// And groups predicates with the AND operator between them.
func And(predicates ...predicate.KnowledgeSubjectAlias) predicate.KnowledgeSubjectAlias {
	return predicate.KnowledgeSubjectAlias(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.KnowledgeSubjectAlias) predicate.KnowledgeSubjectAlias {
	return predicate.KnowledgeSubjectAlias(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.KnowledgeSubjectAlias) predicate.KnowledgeSubjectAlias {
	return predicate.KnowledgeSubjectAlias(sql.NotPredicates(p))
}
